from collections import deque
from itertools import combinations

def solve(n, s, t, allowed):
    total = n + 2
    def enc(cfg):
        bits = 0
        for j,ch in enumerate(cfg):
            if ch=='B': bits |= 1<<j
        return (n, bits)
    start, goal = enc(s), enc(t)
    if start==goal: return 0
    def neigh(state):
        e,bits = state
        out=[]
        for i in range(total-1):
            o = i - e
            if o not in allowed: continue
            v1=(bits>>i)&1; v2=(bits>>(i+1))&1
            nb = bits & ~((1<<i)|(1<<(i+1))) | (v1<<e) | (v2<<(e+1))
            out.append((i,nb))
        return out
    dist={start:0}; q=deque([start])
    while q:
        st=q.popleft(); d=dist[st]
        for ns in neigh(st):
            if ns not in dist:
                dist[ns]=d+1; q.append(ns)
    return dist.get(goal,-1)

small=[(6,'BWBWBW','WWWBBB',4),(6,'BBBBBB','WWWWWW',-1),
(4,'WWBB','BBWW',3),(4,'BBWW','WWBB',7),(4,'BBWW','WWBB',3),
(3,'BBW','BBW',0),(3,'BBW','WBB',-1),(2,'BW','WB',-1),(2,'BW','BW',0),
(4,'WWBB','WBWB',-1)]
offsets=[-5,-4,-3,-2,2,3,4,5]
found=[]
for r in range(1,9):
    for combo in combinations(offsets,r):
        S=set(combo)
        ok=True
        for n,s,t,exp in small:
            if solve(n,s,t,S)!=exp:
                ok=False; break
        if ok:
            found.append(S)
print(len(found))
for S in found[:20]: print(sorted(S))
