def solve(n, s, t, mode):
    total = n + 2
    def enc(cfg):
        bits = 0
        for j,ch in enumerate(cfg):
            if ch=='B': bits |= 1<<j
        return (n, bits)
    start, goal = enc(s), enc(t)
    if start==goal: return 0
    def neigh(state):
        e,bits = state
        out=[]
        for i in range(total-1):
            if e-1 <= i <= e+1: continue
            v1=(bits>>i)&1; v2=(bits>>(i+1))&1
            if mode=='R1':
                # preserve order when pair left of gap, swap when pair right of gap
                if i < e:
                    nb = bits & ~((1<<i)|(1<<(i+1))) | (v1<<e) | (v2<<(e+1))
                else:
                    nb = bits & ~((1<<i)|(1<<(i+1))) | (v2<<e) | (v1<<(e+1))
            else: # R2
                if i < e:
                    nb = bits & ~((1<<i)|(1<<(i+1))) | (v2<<e) | (v1<<(e+1))
                else:
                    nb = bits & ~((1<<i)|(1<<(i+1))) | (v1<<e) | (v2<<(e+1))
            out.append((i,nb))
        return out
    dist={start:0}; q=deque([start])
    while q:
        st=q.popleft(); d=dist[st]
        for ns in neigh(st):
            if ns not in dist:
                dist[ns]=d+1; q.append(ns)
    return dist.get(goal,-1)

